import { Button, Drawer, Divider, Stack } from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface MenuDrawerProps {
  onNavigate: (key: NavKey) => void;
}

const ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function MenuDrawer({ onNavigate }: MenuDrawerProps) {
  const [open, setOpen] = useState(false);

  const select = useCallback(
    (key: NavKey) => {
      setOpen(false);
      onNavigate(key);
    },
    [onNavigate],
  );

  return (
    <>
      <Button onClick={() => setOpen(true)} aria-haspopup="menu" aria-expanded={open}>
        Меню
      </Button>

