        onClose={() => setOpen(false)}
        aria-label="Навигация"
      >
        <Stack direction="column" gap="var(--jx-space-1)" role="menu">
          {ITEMS.map((item) => (
            <Button
              key={item.key}
              role="menuitem"
              variant="ghost"
              fullWidth
              onClick={() => select(item.key)}
            >
              {item.label}
